// A API retorna o vetor como array JS.
// O Postgres espera o literal de vetor: '[0.1,0.2,...]'
const vetor = $json.data?.[0]?.embedding;

if (!Array.isArray(vetor) || vetor.length !== 1536) {
  throw new Error(`Embedding invalido: esperado array de 1536, recebido ${vetor?.length ?? typeof vetor}`);
}

return [{
  json: {
    tenant_id: $('Quando executado por outro workflow').first().json.tenant_id,
    embedding_literal: '[' + vetor.join(',') + ']'
  }
}];

// Consolida os trechos num unico texto para o LLM.
// Retorna string vazia explicita quando nao ha resultado, para o
// agente saber que precisa transferir em vez de inventar resposta.
const itens = $input.all().map(i => i.json).filter(r => r && r.text);

if (itens.length === 0) {
  return [{ json: { resposta: 'NENHUM_RESULTADO: a base de conhecimento não contém informação sobre esta pergunta.' } }];
}

const texto = itens
  .map((r, i) => `[Trecho ${i + 1} | relevância ${Number(r.similarity).toFixed(3)}]
${r.text}`)
  .join('

---

');

// AVISO DE FONTE DE PRECO.
//
// Quando o tenant tem vendas contratada, o catalogo e a fonte unica de preco --
// a base de conhecimento e material de referencia. O documento do cliente pode
// conter tabela de preco antiga: no restaurante-teste a base dizia 94,00 para um
// prato que o catalogo cobra 149,90. Sem aviso o agente cota da base e o
// adicionar_item grava do catalogo, e o cliente ve um preco e paga outro.
//
// ISTO NAO CONSERTA O DADO INCONSISTENTE, e nao se deve fingir que conserta: e
// instrucao ao modelo, probabilistica. O conserto e o onboarding do modulo
// migrar os precos do documento para o catalogo (ver docs/VENDAS-ESTADO.md).
// O aviso existe para encurtar a janela ate isso acontecer.
const vende = itens.some(r => r.vende === true);

const AVISO =
  'AVISO DE FONTE (instrucao interna, nao repasse ao cliente): este cliente tem ' +
  'catalogo de vendas ativo. Preco e disponibilidade validos sao os de ' +
  'consultar_catalogo. Valores que aparecam nos trechos acima sao referencia e ' +
  'podem estar desatualizados — nao cote preco a partir deles.';

return [{ json: { resposta: vende ? texto + '

---

' + AVISO : texto } }];
